export const GUIDE_HTML: string = "<p>Nov 24, 2026 · </p>\n<span id=\"overview\"></span><h2 id=\"연수-개요\">연수 개요</h2>\n<p>AI 입문 교사가 3시간 뒤 <strong>ChatGPT로 자기 업무 도구 1개를 직접 만들어 가는 것</strong>이 목표다. 개념(1교시) → 도구 지도(2교시) → 실습(3교시) 순서로, 실습 시간을 가장 길게 둔다.</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">항목</th>\n<th scope=\"col\">내용</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>대상</td>\n<td>고등학교 교사, AI 입문 수준 (ChatGPT를 가끔 써 본 정도)</td>\n</tr>\n<tr>\n<td>시수</td>\n<td>3시간 = 50분 × 3교시 + 쉬는 시간 10분 × 2</td>\n</tr>\n<tr>\n<td>실습 도구</td>\n<td>ChatGPT (무료 계정 가능, 유료면 Work·GPTs·Sites까지 체험)</td>\n</tr>\n<tr>\n<td>준비물</td>\n<td>노트북, ChatGPT 계정(사전 가입 안내), 각자 업무 자료 1개(개인정보 지운 것)</td>\n</tr>\n<tr>\n<td>산출물</td>\n<td>① 나만의 업무 프롬프트 1개 ② 맞춤형 GPT 또는 프로젝트 1개 ③ 수업용 미니 도구 시안</td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">교시</th>\n<th scope=\"col\">시간</th>\n<th scope=\"col\">주제</th>\n<th scope=\"col\">활동</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1교시</td>\n<td>50분</td>\n<td>LLM 개념 + 필수 용어</td>\n<td>강의 30분, 퀴즈·질문 20분</td>\n</tr>\n<tr>\n<td>2교시</td>\n<td>50분</td>\n<td>상용 AI 지도, Chat/Work/Code, 스킬·MCP</td>\n<td>강의 25분, 업무↔AI 짝짓기 25분</td>\n</tr>\n<tr>\n<td>3교시</td>\n<td>50분</td>\n<td>실습 프로젝트 3단계 + 학생 수업 적용</td>\n<td>실습 40분, 공유 10분</td>\n</tr>\n</tbody></table>\n<blockquote>\n<p>사전 공지: 학생 이름·성적·상담 내용 등 개인정보는 실습에 넣지 않는다.</p>\n</blockquote>\n<span id=\"period-1\"></span><h2 id=\"1교시-가-llm의-개념-챗봇-워크플로우-ai-에이전트\">1교시 (가) LLM의 개념: 챗봇 → 워크플로우 → AI 에이전트</h2>\n<p>핵심 메시지: <strong>능력은 같은 LLM이고, 달라지는 것은 ‘누가 다음 단계를 정하느냐’다.</strong> 챗봇은 사람이, 워크플로우는 미리 짠 순서가, 에이전트는 AI가 스스로 정한다.</p>\n<p><strong>LLM(대규모 언어 모델) 한 줄 설명</strong>: 방대한 글을 학습해 ‘다음에 올 말’을 예측하는 모델. 그래서 그럴듯하게 틀릴 수 있다(환각).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">구분</th>\n<th scope=\"col\">누가 다음 단계를 정하나</th>\n<th scope=\"col\">학교 예시</th>\n<th scope=\"col\">ChatGPT에서</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>챗봇</td>\n<td>사람이 매번 질문</td>\n<td>“수행평가 루브릭 초안 써줘”</td>\n<td>일반 채팅</td>\n</tr>\n<tr>\n<td>워크플로우</td>\n<td>미리 정한 순서(항상 같은 길)</td>\n<td>설문 응답 → 요약 → 가정통신문 초안 자동 생성</td>\n<td>맞춤형 GPT, 예약 작업</td>\n</tr>\n<tr>\n<td>AI 에이전트</td>\n<td>AI가 목표를 보고 계획·도구 사용·수정</td>\n<td>“다음 주 현장체험학습 자료 조사해서 안내문과 체크리스트 만들어”</td>\n<td>ChatGPT Work(에이전트), Codex</td>\n</tr>\n</tbody></table>\n<p><strong>교사가 알아야 할 4가지 한계</strong></p>\n<ul>\n<li>환각: 없는 출처·법령·통계를 지어낼 수 있다 → 공문·수치는 반드시 원문 확인</li>\n<li>최신성: 학습 시점 이후 정보는 검색 기능을 켜야 반영</li>\n<li>개인정보: 입력한 내용이 외부 서버로 간다 → 학생 실명·성적 금지</li>\n<li>책임: 최종 판단과 서명은 교사가 한다</li>\n</ul>\n<p><strong>현장 퀴즈(5분)</strong>: “매주 금요일 주간학습안내를 같은 양식으로 만든다”는 챗봇·워크플로우·에이전트 중 무엇이 맞을까? (정답: 워크플로우)</p>\n<span id=\"terms\"></span><h2 id=\"1교시-나-필수-용어-정리\">1교시 (나) 필수 용어 정리</h2>\n<p>AI로 ‘무언가를 만들기’ 시작하면 아래 용어가 반드시 나온다. 비유는 ‘식당’으로 통일한다.</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">용어</th>\n<th scope=\"col\">뜻(한 줄)</th>\n<th scope=\"col\">식당 비유</th>\n<th scope=\"col\">학교 예시</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>프론트엔드</td>\n<td>사용자가 보고 누르는 화면</td>\n<td>홀·메뉴판</td>\n<td>퀴즈 웹페이지의 버튼·글자</td>\n</tr>\n<tr>\n<td>백엔드</td>\n<td>보이지 않는 곳에서 데이터를 처리·저장</td>\n<td>주방</td>\n<td>제출한 답을 채점·저장하는 부분</td>\n</tr>\n<tr>\n<td>데이터베이스(DB)</td>\n<td>자료를 정리해 두는 저장소</td>\n<td>창고·장부</td>\n<td>제출 기록 표</td>\n</tr>\n<tr>\n<td>API</td>\n<td>프로그램끼리 요청·응답하는 약속된 창구</td>\n<td>주문서 양식</td>\n<td>웹페이지가 GPT에게 질문을 보내는 통로</td>\n</tr>\n<tr>\n<td>MVP</td>\n<td>핵심 기능만 넣은 최소 시제품</td>\n<td>메뉴 하나로 개업해 반응 보기</td>\n<td>문제 5개짜리 퀴즈로 먼저 수업해 보기</td>\n</tr>\n<tr>\n<td>PWA</td>\n<td>앱처럼 설치되는 웹페이지</td>\n<td>배달 앱 없이 단골 버튼</td>\n<td>폰 홈 화면에 추가하는 학급 알림장</td>\n</tr>\n<tr>\n<td>배포</td>\n<td>만든 것을 인터넷 주소로 공개</td>\n<td>간판 달고 문 열기</td>\n<td>링크를 학생에게 공유</td>\n</tr>\n<tr>\n<td>프롬프트</td>\n<td>AI에게 주는 지시문</td>\n<td>주문</td>\n<td>“고1 수준, 10문항, 표로”</td>\n</tr>\n<tr>\n<td>컨텍스트</td>\n<td>AI가 한 번에 참고하는 자료의 범위</td>\n<td>주문 시 건네는 메모</td>\n<td>체크한 교육과정 문서</td>\n</tr>\n<tr>\n<td>토큰</td>\n<td>AI가 글을 세는 단위(사용량·비용 기준)</td>\n<td>주문량</td>\n<td>긴 문서일수록 많이 소모</td>\n</tr>\n</tbody></table>\n<p><strong>요약 한 문장</strong>: “MVP로 작게 만들고, 프론트엔드만으로 충분하면 백엔드 없이, 필요하면 PWA로 폰에 올린다.”</p>\n<span id=\"quiz-app\"></span><h2 id=\"1교시-나-용어-실전-퀴즈-앱-하나-뜯어보기\">1교시 (나+) 용어 실전: 퀴즈 앱 하나 뜯어보기</h2>\n<p>학생이 퀴즈에서 <strong>[제출] 버튼을 누른 0.5초 동안</strong> 프론트엔드 → API → 백엔드 → 데이터베이스를 한 바퀴 돈다. 이 한 바퀴를 보여주면 네 용어가 한 번에 잡힌다.</p>\n<p><strong>제출 버튼을 누르면 일어나는 일</strong></p>\n<ol>\n<li>프론트엔드(학생 폰 화면): 고른 답 ③을 읽는다.</li>\n<li>API 요청: “1번 문제, 답 ③”을 정해진 양식(JSON)에 담아 서버 주소로 보낸다.</li>\n<li>백엔드(서버): 정답과 비교해 채점한다. 정답은 학생 화면에 없고 서버에만 있다(부정행위 방지).</li>\n<li>데이터베이스: “언제, 몇 번, 무슨 답, 맞았는지”를 한 줄 저장한다.</li>\n<li>API 응답: “오답, 힌트: …”를 돌려보낸다.</li>\n<li>프론트엔드: 화면에 힌트를 띄운다. 교사는 나중에 DB를 보고 오답률이 높은 문항을 찾는다.</li>\n</ol>\n<p><strong>① 프론트엔드 — 학생이 보는 화면 (HTML + 자바스크립트)</strong></p>\n<pre><code class=\"language-html\">&lt;p&gt;1. 온실가스가 아닌 것은?&lt;/p&gt;\n&lt;label&gt;&lt;input type=&quot;radio&quot; name=&quot;q1&quot; value=&quot;3&quot;&gt; ③ 산소&lt;/label&gt;\n&lt;button id=&quot;submit&quot;&gt;제출&lt;/button&gt;\n&lt;script&gt;\n  submit.onclick = async () =&gt; {\n    const answer = document.querySelector(&#39;input[name=q1]:checked&#39;).value;\n    const res = await fetch(&#39;/api/submit&#39;, {          // ② API 호출\n      method: &#39;POST&#39;,\n      body: JSON.stringify({ question: 1, answer })\n    });\n    const result = await res.json();\n    alert(result.correct ? &#39;정답!&#39; : &#39;힌트: &#39; + result.hint);\n  };\n&lt;/script&gt;\n</code></pre>\n<p><strong>② API — 오가는 주문서(요청과 응답)</strong></p>\n<pre><code class=\"language-json\">요청  POST /api/submit   { &quot;question&quot;: 1, &quot;answer&quot;: &quot;3&quot; }\n응답  200 OK             { &quot;correct&quot;: true, &quot;hint&quot;: &quot;&quot; }\n</code></pre>\n<p><strong>③ 백엔드 — 보이지 않는 주방 (서버 함수 예)</strong></p>\n<pre><code class=\"language-javascript\">const ANSWERS = { 1: &#39;3&#39;, 2: &#39;1&#39; };          // 정답은 서버에만\nexport default async (req) =&gt; {\n  const { question, answer } = await req.json();\n  const correct = ANSWERS[question] === answer;\n  await db.insert(&#39;submissions&#39;, { question, answer, correct, at: new Date() }); // ④ DB 저장\n  return Response.json({ correct, hint: correct ? &#39;&#39; : &#39;광합성에서 나오는 기체를 떠올려 보세요&#39; });\n};\n</code></pre>\n<p><strong>④ 데이터베이스 — 저장된 장부(submissions 표)</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">id</th>\n<th scope=\"col\">question</th>\n<th scope=\"col\">answer</th>\n<th scope=\"col\">correct</th>\n<th scope=\"col\">at</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>101</td>\n<td>1</td>\n<td>3</td>\n<td>true</td>\n<td>2026-11-24 09:12</td>\n</tr>\n<tr>\n<td>102</td>\n<td>1</td>\n<td>2</td>\n<td>false</td>\n<td>2026-11-24 09:12</td>\n</tr>\n<tr>\n<td>103</td>\n<td>2</td>\n<td>1</td>\n<td>true</td>\n<td>2026-11-24 09:13</td>\n</tr>\n</tbody></table>\n<p><strong>실제로 이미 쓰고 있는 API 예시 — 나이스 급식 식단</strong></p>\n<p>교육청 나이스 교육정보 개방 포털(open.neis.go.kr)은 급식 식단·학사일정·시간표를 API로 준다. 주소에 학교 코드와 날짜를 넣으면 그날 메뉴가 JSON으로 온다. 실제로는 포털에서 인증키를 발급받아 KEY=인증키를 붙이고, 연수 전 실제 호출로 확인한다. “오늘 급식 알려주는 학급 페이지”가 바로 이 API를 부르는 프론트엔드다.</p>\n<pre><code class=\"language-text\">https://open.neis.go.kr/hub/mealServiceDietInfo?Type=json\n  &amp;ATPT_OFCDC_SC_CODE=[교육청코드]&amp;SD_SCHUL_CODE=[학교코드]&amp;MLSV_YMD=20261124\n</code></pre>\n<p><strong>만들 때 고르는 법(현장 판단)</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">필요한 것</th>\n<th scope=\"col\">구성</th>\n<th scope=\"col\">ChatGPT에서</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>보여주기만(안내 페이지, 자가 채점 퀴즈)</td>\n<td>프론트엔드만</td>\n<td>캔버스 HTML 파일</td>\n</tr>\n<tr>\n<td>기록을 모아야(제출, 투표, 설문)</td>\n<td>프론트 + 백엔드 + DB</td>\n<td>Sites(저장·DB 지원)</td>\n</tr>\n<tr>\n<td>다른 서비스 자료를 가져와야(급식, 날씨)</td>\n<td>프론트 + 외부 API</td>\n<td>Sites 또는 Codex</td>\n</tr>\n</tbody></table>\n<p>교사가 코드를 직접 쓸 필요는 없다. 다만 “제출 기록을 저장해줘(=DB)”, “정답은 서버에만 둬(=백엔드)”처럼 <strong>용어로 요청할 수 있으면 결과물 품질이 달라진다</strong>.</p>\n<span id=\"period-2\"></span><h2 id=\"2교시-다-상용-ai-지도와-chat-work-code\">2교시 (다) 상용 AI 지도와 Chat / Work / Code</h2>\n<p>2026년 현재 주요 AI는 모두 <strong>‘대화(Chat) · 일 맡기기(Work) · 코딩(Code)’ 3층 구조</strong>로 수렴했다. ChatGPT도 2026년 7월 ChatGPT Work를 내놓으며 Chat·Work·Codex를 한 앱에 묶었다(<a href=\"https://openai.com/index/chatgpt-for-your-most-ambitious-work\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI 발표</a>).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">층</th>\n<th scope=\"col\">한 줄 정의</th>\n<th scope=\"col\">결과물</th>\n<th scope=\"col\">교사가 할 수 있는 일</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Chat</td>\n<td>묻고 답하기</td>\n<td>답변·초안 텍스트</td>\n<td>발문 아이디어, 가정통신문 초안, 개념 설명</td>\n</tr>\n<tr>\n<td>Work</td>\n<td>목표를 주고 맡기기(에이전트)</td>\n<td>파일: 문서·슬라이드·표·웹페이지</td>\n<td>여러 자료 모아 수업 슬라이드, 평가 결과 표 정리, 행사 안내 사이트</td>\n</tr>\n<tr>\n<td>Code</td>\n<td>코드를 짜고 실행·배포</td>\n<td>동작하는 프로그램</td>\n<td>퀴즈 앱, 자리배치 도구, 학급 PWA</td>\n</tr>\n</tbody></table>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">서비스</th>\n<th scope=\"col\">Chat</th>\n<th scope=\"col\">Work(에이전트)</th>\n<th scope=\"col\">Code</th>\n<th scope=\"col\">학교에서 강점</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><a href=\"https://openai.com/index/chatgpt-for-your-most-ambitious-work\" target=\"_blank\" rel=\"noopener noreferrer\">ChatGPT</a></td>\n<td>ChatGPT 채팅, GPTs, 프로젝트</td>\n<td>ChatGPT Work, Sites(베타)</td>\n<td>Codex</td>\n<td>사용자 많음, 교사용 플러그인 등장</td>\n</tr>\n<tr>\n<td><a href=\"https://claude.com/docs/cowork\" target=\"_blank\" rel=\"noopener noreferrer\">Claude</a></td>\n<td>Claude 채팅</td>\n<td>Cowork</td>\n<td>Claude Code</td>\n<td>긴 문서 읽기·글쓰기, 스킬·MCP 원조</td>\n</tr>\n<tr>\n<td>Gemini</td>\n<td>Gemini 앱, NotebookLM</td>\n<td>Workspace 연동 에이전트</td>\n<td>코딩 도구</td>\n<td>구글 클래스룸·드라이브 연동</td>\n</tr>\n<tr>\n<td>Microsoft Copilot</td>\n<td>Copilot 채팅</td>\n<td>M365(워드·엑셀·파워포인트) 안</td>\n<td>GitHub Copilot</td>\n<td>한글 외 오피스 문서 업무</td>\n</tr>\n<tr>\n<td>Perplexity</td>\n<td>검색형 채팅</td>\n<td>—</td>\n<td>—</td>\n<td>출처 달린 조사</td>\n</tr>\n</tbody></table>\n<p><strong>시연 예시(같은 요청, 3층 비교)</strong>: “기후변화 단원 평가를 도와줘”</p>\n<ol>\n<li>Chat: 문항 10개 초안을 텍스트로 받는다.</li>\n<li>Work: 문항·정답표·루브릭이 든 문서 파일을 받는다.</li>\n<li>Code: 학생이 풀고 바로 채점되는 퀴즈 웹페이지를 받는다.</li>\n</ol>\n<p>참고: 기능·요금제별 제공 범위는 자주 바뀜다. 연수 전날 실제 화면으로 다시 확인한다.</p>\n<span id=\"chatgpt-work\"></span><h2 id=\"2교시-다-1-chatgpt-work-자세히\">2교시 (다-1) ChatGPT Work 자세히</h2>\n<p>ChatGPT Work는 <strong>목표를 주면 스스로 단계를 나눠 자료를 모으고, 문서·슬라이드·시트·사이트 같은 완성물을 내는 에이전트</strong>다. 2026년 7월 9일 출시, Codex 기술 기반이며 몇 시간짜리 작업도 이어서 한다(<a href=\"https://openai.com/index/chatgpt-for-your-most-ambitious-work\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI</a>).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">항목</th>\n<th scope=\"col\">내용</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>어디서</td>\n<td>웹·모바일의 Work, 데스크톱 앱의 Work 탭(Chat·Work·Codex 중 선택)</td>\n</tr>\n<tr>\n<td>누가</td>\n<td>웹·모바일: Pro·Enterprise·Edu 우선, 이어 Plus·Business / 데스크톱 앱: Free 포함 전 요금제(사용량 한도 다름)</td>\n</tr>\n<tr>\n<td>자료 연결</td>\n<td>플러그인(구글 드라이브, 메일, 캘린더, 팀즈 등). 프롬프트에 @앱이름으로 지정</td>\n</tr>\n<tr>\n<td>사람의 역할</td>\n<td>진행 상황 보기, 질문에 답하기, 방향 바꾸기, 중요한 동작(발송·수정) 승인</td>\n</tr>\n<tr>\n<td>예약 작업</td>\n<td>한 번 / 반복 / 이벤트 발생 시 / 변화 감시. 예: 매주 금요일 오후 주간학습안내 초안</td>\n</tr>\n</tbody></table>\n<p><strong>실제 작업에서는 이렇게 돌아간다 — “현장체험학습 준비” 예시</strong></p>\n<p>요청: “@Google Drive의 ‘현장체험 계획서’를 읽고, 가정통신문·학생 안전 체크리스트·당일 시간표 슬라이드를 만들어 줘. 발송은 하지 말고 초안만.”</p>\n<ol>\n<li><strong>계획</strong> — 화면에 할 일 4개를 적는다: 계획서 찾기 → 핵심 정보 뽑기 → 문서 2개 → 슬라이드 1개.</li>\n<li><strong>플러그인 호출</strong> — 드라이브에서 ‘현장체험’ 검색 → 파일 2개 발견 → 내용 읽기(날짜·장소·인솔·비용).</li>\n<li><strong>모르는 것은 묻기</strong> — “계획서에 집합 시각이 두 개입니다. 8:30과 8:00 중 무엇인가요?”</li>\n<li><strong>산출물 생성</strong> — 가정통신문(문서), 체크리스트(표), 시간표(슬라이드) 파일을 만든다.</li>\n<li><strong>스스로 점검</strong> — 날짜·금액이 계획서와 같은지 대조한다.</li>\n<li><strong>승인 대기</strong> — 드라이브에 저장하거나 메일을 보내기 전에 “저장할까요?”를 묻는다.</li>\n</ol>\n<p><strong>Chat과 Work, 같은 요청의 차이</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\"><span class=\"sr-only\">구분</span></th>\n<th scope=\"col\">Chat</th>\n<th scope=\"col\">Work</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>입력</td>\n<td>교사가 내용을 붙여 넣음</td>\n<td>@드라이브에서 직접 찾아 읽음</td>\n</tr>\n<tr>\n<td>과정</td>\n<td>한 번에 답</td>\n<td>계획 → 실행 → 점검, 중간 질문</td>\n</tr>\n<tr>\n<td>결과</td>\n<td>채팅 텍스트</td>\n<td>문서·표·슬라이드 파일 3개</td>\n</tr>\n<tr>\n<td>시간</td>\n<td>수십 초</td>\n<td>수 분~수십 분</td>\n</tr>\n</tbody></table>\n<p><strong>학교 업무 시나리오 (프롬프트 그대로 사용)</strong></p>\n<ul>\n<li>“업로드한 수행평가 계획서로 루브릭 표, 학생용 안내문, 채점 시트 템플릿을 만들어 줘.”</li>\n<li>“설문 결과 엑셀을 분석해 학부모 설명회용 슬라이드 8장으로 정리해 줘. 그래프 포함.”</li>\n<li>“매주 금요일 15시에 @Google Drive의 다음 주 학사 일정을 읽고 주간학습안내 초안을 만들어 두어”(예약 작업).</li>\n</ul>\n<p>주의: 학교 계정을 연결하면 Work가 그 안의 자료를 읽는다. 학생 개인정보가 담긴 폴더는 연결 범위에서 뺀다.</p>\n<span id=\"chatgpt-sites\"></span><h2 id=\"2교시-다-2-chatgpt-sites-자세히\">2교시 (다-2) ChatGPT Sites 자세히</h2>\n<p>Sites는 <strong>말로 설명하면 웹사이트·가벼운 앱을 만들고, 주소(URL)까지 발급해 주는 기능</strong>이다. 호스팅·접근 권한·저장소·데이터베이스가 포함돼 있어, 1교시의 ‘프론트 + 백엔드 + DB + 배포’를 한 번에 처리한다(<a href=\"https://help.openai.com/en/articles/20001339\" target=\"_blank\" rel=\"noopener noreferrer\">도움말</a>, <a href=\"https://openai.com/academy/chatgpt-sites\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI Academy</a>).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">항목</th>\n<th scope=\"col\">내용</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>상태</td>\n<td>공개 베타. Free·Go를 제외한 유료 요금제, 요금제별 사용량 한도 있음</td>\n</tr>\n<tr>\n<td>만드는 곳</td>\n<td>웹의 Work, 데스크톱 앱의 Work 또는 Codex. 프롬프트에 @Sites</td>\n</tr>\n<tr>\n<td>공개 범위</td>\n<td>나만(기본) → 지정한 사람 → 워크스페이스 → 인터넷 누구나</td>\n</tr>\n<tr>\n<td>주의</td>\n<td>배포하는 주소는 모두 실제 운영 주소. 고칠 때는 버전 저장 → 확인 → 배포 순서</td>\n</tr>\n</tbody></table>\n<p><strong>만들기부터 공유까지 7단계</strong></p>\n<ol>\n<li>Work를 열고 “@Sites …을 만들어 줘”라고 설명한다.</li>\n<li>ChatGPT가 비공개 미리보기를 만든다.</li>\n<li>미리보기를 눌러 보며 테스트한다(폰 화면 포함).</li>\n<li>“제출 버튼을 더 크게”처럼 한 가지씩 수정을 요청한다.</li>\n<li>배포(Deploy)하면 주소가 생긴다. 이때는 아직 나만 볼 수 있다.</li>\n<li>공유(Share)에서 공개 범위를 고른다. 학생용이면 링크 공개, 동료용이면 지정한 사람.</li>\n<li>동료에게 ‘편집 가능’ 권한을 주면 함께 고칠 수 있다(같은 워크스페이스).</li>\n</ol>\n<p><strong>학교에서 바로 쓸 수 있는 Site 예시</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">Site</th>\n<th scope=\"col\">프롬프트 예</th>\n<th scope=\"col\">쓰는 기능</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>단원 형성평가 퀴즈</td>\n<td>“@Sites 이 문항 5개로 퀴즈 사이트, 문항별 오답률을 교사만 보게”</td>\n<td>프론트 + DB + 접근 권한</td>\n</tr>\n<tr>\n<td>동아리 모집 페이지</td>\n<td>“동아리 소개, 활동 사진, 지원 양식이 있는 페이지”</td>\n<td>프론트 + 제출 저장</td>\n</tr>\n<tr>\n<td>학급 알림판</td>\n<td>“주간 일정·준비물을 보여주는 학급 페이지, 내가 매주 수정”</td>\n<td>프론트 + 교사 편집</td>\n</tr>\n<tr>\n<td>학생 투표·설문</td>\n<td>“체험학습 장소 3곳 투표, 결과는 막대그래프”</td>\n<td>프론트 + DB + 집계</td>\n</tr>\n<tr>\n<td>교무실 업무 포털</td>\n<td>“학기 일정·양식 링크·담당자를 모은 내부 페이지”</td>\n<td>워크스페이스 한정 공개</td>\n</tr>\n</tbody></table>\n<p><strong>공개 전 체크</strong></p>\n<ul>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 학생 이름·성적·연락처가 화면이나 데이터에 없는가</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 학생 입력을 받는다면 무엇을 받고 누가 보는지 안내했는가</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 저작권 있는 사진·교과서 지문을 그대로 올리지 않았는가</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 공개 범위가 목적에 맞는가(인터넷 전체 공개는 마지막 선택)</li>\n</ul>\n<p>연수 운영 팁: Free 계정 교사는 Sites가 없다. 3교시 3단계는 ‘캔버스 HTML’(무료)과 ‘Sites’(유료) 두 갈래로 안내한다.</p>\n<span id=\"skills\"></span><h2 id=\"2교시-라-스킬과-mcp\">2교시 (라) 스킬과 MCP</h2>\n<p><strong>스킬 = AI에게 주는 ‘업무 매뉴얼’, MCP = AI를 다른 프로그램에 꼽는 ‘표준 콘센트(USB-C)’.</strong> 스킬은 ‘어떻게 할지’, MCP는 ‘무엇에 접근할지’를 담당한다.</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">구분</th>\n<th scope=\"col\">스킬(Skill)</th>\n<th scope=\"col\">MCP(Model Context Protocol)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>비유</td>\n<td>신규 교사용 업무 매뉴얼</td>\n<td>노트북의 USB-C 단자</td>\n</tr>\n<tr>\n<td>정체</td>\n<td>지시문·예시·양식을 담은 폴더(SKILL.md)</td>\n<td>AI와 외부 서비스를 잇는 공개 표준</td>\n</tr>\n<tr>\n<td>역할</td>\n<td>매번 설명할 필요 없이 같은 품질로 반복</td>\n<td>구글 드라이브·캘린더·노션 등을 읽고 쓰기</td>\n</tr>\n<tr>\n<td>학교 예시</td>\n<td>“우리 학교 가정통신문 양식·말투로 작성”</td>\n<td>“드라이브의 수행평가 계획서를 읽고 캘린더에 일정 등록”</td>\n</tr>\n<tr>\n<td>ChatGPT에서</td>\n<td>스킬(Work·Codex에서 @로 호출)</td>\n<td>앱(예전 이름: 커넥터)</td>\n</tr>\n<tr>\n<td>Claude에서</td>\n<td>스킬</td>\n<td>커넥터</td>\n</tr>\n</tbody></table>\n<ul>\n<li><strong>플러그인</strong> = 스킬 + 앱(MCP)을 한 꼾음으로 묶은 설치 단위. ChatGPT는 2026년 7월부터 플러그인 디렉터리로 제공한다(<a href=\"https://help.openai.com/en/articles/11487775-apps-in-chatgpt?gn=1\" target=\"_blank\" rel=\"noopener noreferrer\">도움말</a>).</li>\n<li>MCP는 2024년 11월 Anthropic이 공개한 표준으로, ChatGPT·Claude·Copilot 등이 함께 쓴다. 한 번 만든 연결을 여러 AI에서 쓸 수 있다.</li>\n<li>주의: 앱을 연결하면 AI가 그 계정의 자료에 접근한다. 학교 계정 연결은 학교 정보보안 지침을 먼저 확인한다.</li>\n</ul>\n<p><strong>입문자용 체험</strong>: 스킬을 직접 만들 필요는 없다. “방금 한 작업을 다음에도 쓸 수 있게 정리해줘”라고 하면 AI가 지침을 만들어 준다. 무료 계정이면 같은 원리를 맞춤형 GPT의 ‘지침’ 칸으로 체험한다.</p>\n<span id=\"skills-mcp-practice\"></span><h2 id=\"2교시-라-1-스킬플러그인mcp-실제-적용하기\">2교시 (라-1) 스킬·플러그인·MCP 실제 적용하기</h2>\n<p>순서는 <strong>① 플러그인 설치로 MCP(앱) 연결 → ② 스킬 만들기 → ③ 둘을 묶어 내 플러그인</strong>이다. 입문 연수에서는 ①·②까지 시연하고 ③은 소개만 한다.</p>\n<p><strong>세 가지를 한 표로 (ChatGPT 기준)</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\"><span class=\"sr-only\">구분</span></th>\n<th scope=\"col\">맞춤형 GPT</th>\n<th scope=\"col\">스킬</th>\n<th scope=\"col\">플러그인</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>무엇</td>\n<td>목적별 ChatGPT 복제본</td>\n<td>작업 절차서(SKILL.md)</td>\n<td>스킬 + 앱(MCP)을 묶은 설치 단위</td>\n</tr>\n<tr>\n<td>부르는 법</td>\n<td>GPT를 골라 대화</td>\n<td>관련 있으면 자동, 또는 @스킬명</td>\n<td>자동, 또는 @플러그인명</td>\n</tr>\n<tr>\n<td>어디서 쓰나</td>\n<td>그 GPT 안에서만</td>\n<td>Chat·Work·Codex, 다른 AI(공개 표준)</td>\n<td>Chat·Work·Codex</td>\n</tr>\n<tr>\n<td>교사 예</td>\n<td>‘형성평가 출제 도우미’</td>\n<td>‘가정통신문 작성’</td>\n<td>‘구글 드라이브’, K–12 교사용 플러그인</td>\n</tr>\n</tbody></table>\n<span id=\"mcp\"></span><h3 id=\"①-플러그인-설치-mcp-연결-chatgpt\">① 플러그인 설치 = MCP 연결 (ChatGPT)</h3>\n<ol>\n<li>사이드바 <strong>Plugins</strong> → “Google Drive” 검색.</li>\n<li>상세 화면에서 포함된 앱·스킬·필요 권한을 확인.</li>\n<li><strong>설치 / 연결</strong> → 구글 로그인 → 권한 허용.</li>\n<li>새 채팅에서 “@Google Drive 에서 2학기 평가 계획서 찾아 요약해 줘”.</li>\n<li>연결 해제는 설정 → Plugins(또는 앱)에서.</li>\n</ol>\n<p>OpenAI 검증 배지(OpenAI Verified)가 있는 플러그인을 우선 쓴다. 플러그인 디렉터리는 모든 요금제에 보이지만 개별 설치 가능 여부는 요금제·지역에 따라 다르다(<a href=\"https://help.openai.com/en/articles/20001256-plugins-in-chatgpt-and-codex\" target=\"_blank\" rel=\"noopener noreferrer\">도움말</a>).</p>\n<p><strong>MCP가 실제로 오가는 모습</strong> — “@Google Calendar 다음 주 화요일 15시에 1학년 협의회 등록해 줘”</p>\n<ol>\n<li>AI가 연결된 캘린더가 제공하는 도구 목록을 확인한다(일정 조회, 일정 만들기 …).</li>\n<li>‘일정 만들기’ 도구를 골라 아래 같은 요청을 만든다.</li>\n<li>쓰기 동작이다. 설정에 따라 실행 전에 승인을 묻거나 바로 실행한다(2026-11-25 연수 준비 중 확인: 승인 없이 바로 등록됨). 그래서 쓰기 권한은 신중히 허용한다.</li>\n<li>캘린더가 결과를 돌려주고, AI가 “등록했습니다”로 답한다.</li>\n</ol>\n<pre><code class=\"language-json\">→ AI가 보내는 도구 호출  create_event { &quot;title&quot;: &quot;1학년 협의회&quot;, &quot;start&quot;: &quot;2026-12-01T15:00&quot;, &quot;end&quot;: &quot;2026-12-01T16:00&quot; }\n← 캘린더의 응답      { &quot;status&quot;: &quot;confirmed&quot;, &quot;link&quot;: &quot;https://calendar.google.com/...&quot; }\n</code></pre>\n<p>1교시의 API와 같은 원리다. 차이는 <strong>사람이 코드를 짜는 대신 AI가 어떤 도구를 언제 부를지 스스로 고른다</strong>는 점이고, MCP는 그 도구 목록과 호출 방식을 표준으로 맞춘 규칙이다.</p>\n<span id=\"skill-create\"></span><h3 id=\"②-스킬-만들기-chatgpt\">② 스킬 만들기 (ChatGPT)</h3>\n<ol>\n<li>채팅에 “가정통신문 작성 스킬을 만들어 줘”라고 입력한다. 기본 포함된 skill-creator 스킬이 작동한다.</li>\n<li>AI가 입력 항목·순서·말투·점검 기준을 물어본다. 예전 가정통신문 1–2개를 업로드하면 품질이 올라간다.</li>\n<li>만들어진 SKILL.md를 확인하고 설치한다.</li>\n<li>새 채팅에서 “12월 결업식 가정통신문 써 줘” → 스킬이 자동으로 쓰인다(또는 @스킬명).</li>\n</ol>\n<p>개인 스킬은 Business·Enterprise·Edu 등 워크스페이스 요금제에서 바로 쓸 수 있고, 데스크톱 앱 Codex에서도 독립 스킬을 쓸 수 있다. 개인 Free·Plus·Pro 요금제에서는 채팅 속 개인 스킬을 쓸 수 없고, Enterprise·Edu는 관리자가 켜야 한다(<a href=\"https://openai.com/academy/skills\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI Academy</a>).</p>\n<p><strong>SKILL.md 실제 예시 — 폴더 하나가 스킬 하나</strong></p>\n<pre><code class=\"language-text\">school-newsletter/\n├── SKILL.md            ← 필수: 이름·설명·절차\n├── assets/\n│   └── template.docx   ← 우리 학교 양식\n└── references/\n    └── examples.md     ← 잘 쓴 가정통신문 2개\n</code></pre>\n<pre><code class=\"language-markdown\">---\nname: school-newsletter\ndescription: ○○고 가정통신문을 학교 양식과 공문체로 작성한다. &quot;가정통신문&quot;, &quot;학부모 안내&quot; 요청에 사용.\n---\n# 가정통신문 작성\n\n## 필요한 입력\n- 행사명, 일시, 장소, 대상, 준비물, 회신 필요 여부\n\n## 절차\n1. 빠진 입력이 있으면 먼저 묻는다\n2. assets/template.docx 양식을 따른다\n3. 인사말 → 안내 본문 → 회신서 순서로 쓴다\n\n## 말투\n- &quot;~하오니&quot;, &quot;~바랍니다&quot; 공문체, 한 문장 40자 이내\n\n## 끝내기 전 점검\n- 날짜와 요일이 맞는가\n- 학생 개인정보가 없는가\n</code></pre>\n<p>스킬은 평소에 <strong>이름과 설명만</strong> AI가 알고 있다가, 요청이 설명과 맞으면 본문을 열어 그대로 따른다. 그래서 description에 ‘언제 쓰는지’를 분명히 적는 것이 핵심이다.</p>\n<h3 id=\"③-더-나아가기\">③ 더 나아가기</h3>\n<ul>\n<li><strong>내 플러그인 만들기</strong>: Plugins → + → Plugin Creator와 대화하며 스킬과 앱을 묶는다.</li>\n<li><strong>학교 자체 서비스 연결(커스텀 MCP)</strong>: Business·Enterprise·Edu 워크스페이스에서 관리자가 MCP 서버 주소를 등록하고 게시한다(<a href=\"https://help.openai.com/articles/12584461\" target=\"_blank\" rel=\"noopener noreferrer\">도움말</a>).</li>\n<li><strong>Claude에서 같은 일</strong>: 설정 → 기능(Capabilities)에서 스킬 업로드, 설정 → 커넥터에서 MCP 연결. 같은 SKILL.md를 그대로 옮겨 쓸 수 있다(Agent Skills 공개 표준).</li>\n</ul>\n<span id=\"recommended\"></span><h2 id=\"2교시-라-2-추천-스킬mcp와-시연\">2교시 (라-2) 추천 스킬·MCP와 시연</h2>\n<p>교사에게 효과가 큰 것은 <strong>구글 드라이브·캘린더 연결(MCP)과 ‘내 학교 양식’ 스킬</strong>이다. 아래 목록에서 연수 당일 실제 화면으로 설치 가능 여부를 확인하고 3개만 시연한다.</p>\n<p><strong>추천 MCP(앱·커넥터)</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">이름</th>\n<th scope=\"col\">할 수 있는 일</th>\n<th scope=\"col\">교사 활용 예</th>\n<th scope=\"col\">ChatGPT</th>\n<th scope=\"col\">Claude</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Google Drive (문서·시트·슬라이드)</td>\n<td>파일 검색·읽기·만들기</td>\n<td>평가 계획서 읽고 안내문 작성</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>Google Calendar</td>\n<td>일정 조회·등록</td>\n<td>학사 일정으로 주간학습안내</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>Gmail</td>\n<td>메일 검색·초안</td>\n<td>공문 메일 요약, 회신 초안</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>Canva</td>\n<td>디자인 생성·편집</td>\n<td>행사 포스터, 수업 카드뉴스</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>Notion</td>\n<td>페이지·DB 읽기·쓰기</td>\n<td>수업 기록, 업무 일지</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>Outlook·Teams·SharePoint (Microsoft, 각각 별도 플러그인)</td>\n<td>메일·팀즈·문서</td>\n<td>MS 환경 학교의 구글 대체</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n<tr>\n<td>GitHub</td>\n<td>코드 저장·배포</td>\n<td>정보 수업, 웹앱 버전 관리</td>\n<td>플러그인</td>\n<td>커넥터</td>\n</tr>\n</tbody></table>\n<p><strong>추천 스킬</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">스킬</th>\n<th scope=\"col\">무엇을 하나</th>\n<th scope=\"col\">구하는 곳</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>skill-creator</td>\n<td>대화로 새 스킬을 만들고 고침</td>\n<td>ChatGPT·Claude 기본 포함</td>\n</tr>\n<tr>\n<td>문서 스킬(docx·pptx·xlsx·pdf)</td>\n<td>워드·파워포인트·엑셀·PDF를 양식대로 생성</td>\n<td>Claude 기본 포함, ChatGPT Work는 내장 기능</td>\n</tr>\n<tr>\n<td>가정통신문 작성(직접 제작)</td>\n<td>학교 양식·공문체 통신문</td>\n<td>위 SKILL.md 예시</td>\n</tr>\n<tr>\n<td>형성평가 출제(직접 제작)</td>\n<td>성취기준 표시 문항·해설·루브릭</td>\n<td>3교시 2단계를 스킬로 변환</td>\n</tr>\n<tr>\n<td>주간학습안내(직접 제작)</td>\n<td>학사 일정 → 고정 양식 안내문</td>\n<td>캘린더 MCP와 함께</td>\n</tr>\n<tr>\n<td>K–12 교사용 플러그인(OpenAI)</td>\n<td>수업 자료·평가·교육과정 정렬</td>\n<td>ChatGPT Edu·ChatGPT for Teachers(미국 K–12 교사 대상) 배포 환경 한정(<a href=\"https://openai.com/index/learn-teach-chatgpt-work-codex\" target=\"_blank\" rel=\"noopener noreferrer\">발표</a>)</td>\n</tr>\n</tbody></table>\n<p><strong>연수 중 시연 3개 (각 3분)</strong></p>\n<ol>\n<li><strong>드라이브 MCP</strong> — “@Google Drive 에서 ‘2학기 지필평가 계획’ 찾아서 학생용 시험 범위 안내문 만들어 줘.” 볼 것: AI가 검색 → 읽기 → 작성하는 중간 기록.</li>\n<li><strong>스킬</strong> — 같은 프롬프트 “결업식 가정통신문 써 줘”를 스킬 없이 / 스킬 있이 비교. 볼 것: 양식·말투·빠진 정보 질문의 차이.</li>\n<li><strong>Canva 연결</strong> — “@Canva 과학의 날 행사 포스터 초안 3개.” 볼 것: 채팅 안에서 디자인이 만들어지고 Canva에서 이어서 편집.</li>\n</ol>\n<p>준비: 시연용 구글 계정에 가상 평가 계획서 1개, 예전 가정통신문 2개를 미리 넣어 둔다(실제 학생 정보 없이).</p>\n<span id=\"matching-activity\"></span><h2 id=\"활동-학교-업무-알맞은-ai-짝짓기\">활동: 학교 업무 ↔ 알맞은 AI 짝짓기</h2>\n<p>고르는 기준은 두 가지다. <strong>결과물이 무엇인가(답변/파일/프로그램)</strong>, 그리고 <strong>어느 자료에 붙어 있나(구글/MS/웹)</strong>. 아래 표의 ‘추천’ 열을 가리고 모둠별로 먼저 짝지어 본 뒤 공개한다(15분).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">학교 업무</th>\n<th scope=\"col\">결과물</th>\n<th scope=\"col\">추천 층</th>\n<th scope=\"col\">추천 도구(예)</th>\n<th scope=\"col\">이유</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>가정통신문·안내문 초안</td>\n<td>텍스트</td>\n<td>Chat</td>\n<td>ChatGPT</td>\n<td>짧고 빠름</td>\n</tr>\n<tr>\n<td>수업 발문·활동 아이디어</td>\n<td>텍스트</td>\n<td>Chat</td>\n<td>ChatGPT, Claude</td>\n<td>대화하며 다듬기</td>\n</tr>\n<tr>\n<td>교과서·연수 자료 요약·질문</td>\n<td>요약·답변</td>\n<td>Chat</td>\n<td>NotebookLM</td>\n<td>올린 자료 안에서만 답함</td>\n</tr>\n<tr>\n<td>최신 정책·진학 정보 조사</td>\n<td>출처 달린 요약</td>\n<td>Chat(검색)</td>\n<td>Perplexity, ChatGPT 검색</td>\n<td>출처 확인 가능</td>\n</tr>\n<tr>\n<td>수행평가 루브릭 + 평가지 파일</td>\n<td>문서 파일</td>\n<td>Work</td>\n<td>ChatGPT Work, Claude Cowork</td>\n<td>여러 단계를 한 번에</td>\n</tr>\n<tr>\n<td>연수·수업 슬라이드 제작</td>\n<td>슬라이드</td>\n<td>Work</td>\n<td>ChatGPT Work, Claude, Gamma</td>\n<td>파일로 완성</td>\n</tr>\n<tr>\n<td>엑셀 성적·설문 결과 정리</td>\n<td>표·그래프</td>\n<td>Work</td>\n<td>ChatGPT Work, Copilot in Excel</td>\n<td>표 계산 + 시각화</td>\n</tr>\n<tr>\n<td>구글 클래스룸·드라이브 자료 정리</td>\n<td>문서·폴더</td>\n<td>Work</td>\n<td>Gemini(Workspace)</td>\n<td>자료가 구글에 있음</td>\n</tr>\n<tr>\n<td>주간학습안내 매주 반복</td>\n<td>같은 양식 문서</td>\n<td>Work + 스킬</td>\n<td>맞춤형 GPT, 스킬</td>\n<td>양식 고정 반복</td>\n</tr>\n<tr>\n<td>학생용 퀴즈·단어장 웹앱</td>\n<td>프로그램(링크)</td>\n<td>Code</td>\n<td>Codex, ChatGPT Sites, Claude Code</td>\n<td>학생이 직접 사용</td>\n</tr>\n<tr>\n<td>동아리·학급 알림 PWA</td>\n<td>앱</td>\n<td>Code</td>\n<td>Codex, Claude Code</td>\n<td>폰 설치형</td>\n</tr>\n</tbody></table>\n<p><strong>판단 흐름</strong>: 답만 필요하면 Chat → 파일이 필요하면 Work → 학생이 직접 쓸 도구면 Code. 같은 일을 매주 하면 스킬·맞춤형 GPT로 고정한다.</p>\n<span id=\"high-school\"></span><h2 id=\"고등학생과-llm으로-수업한다면\">고등학생과 LLM으로 수업한다면</h2>\n<p>원칙은 AI가 대신 해 주는 수업이 아니라 <strong>AI의 답을 검증·비판하는 수업</strong>이다. 평가는 결과물보다 과정(프롬프트 기록·수정 이유)에 비중을 둔다.</p>\n<p><strong>수업 전 체크</strong></p>\n<ul>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 서비스 이용 연령 기준과 보호자 동의 필요 여부 확인(서비스별 약관)</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 학교·교육청의 생성형 AI 활용 지침 확인</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 개인 계정 대신 교사 시연·모둠 1계정·교육용 플랫폼 중 운영 방식 결정</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> ‘AI 사용 표시’ 규칙 안내(어디에 어떻게 썼는지 적기)</li>\n</ul>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">교과</th>\n<th scope=\"col\">수업 아이디어</th>\n<th scope=\"col\">AI 역할</th>\n<th scope=\"col\">학생이 하는 일</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>국어</td>\n<td>AI가 쓴 설득문 고쳐 쓰기</td>\n<td>초안 제공</td>\n<td>논지 오류 찾기, 근거 보강</td>\n</tr>\n<tr>\n<td>영어</td>\n<td>AI와 역할극 대화</td>\n<td>대화 상대</td>\n<td>표현 기록, 틀린 말 피드백 비교</td>\n</tr>\n<tr>\n<td>수학</td>\n<td>AI 풀이의 오류 찾기</td>\n<td>일부러 틀릴 수 있는 풀이</td>\n<td>단계별 검증</td>\n</tr>\n<tr>\n<td>사회</td>\n<td>같은 쟁점, 여러 AI 답 비교</td>\n<td>관점 제시</td>\n<td>편향·출처 검증</td>\n</tr>\n<tr>\n<td>과학</td>\n<td>가설 세우기·실험 설계 피드백</td>\n<td>조언자</td>\n<td>실험 후 AI 예측과 비교</td>\n</tr>\n<tr>\n<td>정보</td>\n<td>말로 웹앱 MVP 만들기</td>\n<td>코드 생성</td>\n<td>요구사항 작성, 테스트, 수정 요청</td>\n</tr>\n<tr>\n<td>진로</td>\n<td>직업 인터뷰 시뮬레이션</td>\n<td>직업인 역할</td>\n<td>질문 설계, 실제 자료와 대조</td>\n</tr>\n</tbody></table>\n<p><strong>1차시 수업 흐름 예(50분)</strong>: 도입 5분(AI 한계 사례) → AI 사용 15분 → 검증·수정 20분 → 성찰 기록 10분(“AI가 틀린 점, 내가 바꾼 점”).</p>\n<span id=\"period-3\"></span><span id=\"practice-steps\"></span><h2 id=\"3교시-실습-프로젝트-3단계-chatgpt\">3교시 실습 프로젝트 3단계 (ChatGPT)</h2>\n<p>주제는 하나로 통일한다: <strong>“내 과목 한 단원의 형성평가 도구 만들기”</strong>. 같은 주제를 Chat → 맞춤형 GPT → 웹페이지로 키우며 3층 구조를 몸으로 익힌다.</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">단계</th>\n<th scope=\"col\">시간</th>\n<th scope=\"col\">목표</th>\n<th scope=\"col\">산출물</th>\n<th scope=\"col\">관련 개념</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1. 프롬프트 다듬기</td>\n<td>12분</td>\n<td>좋은 지시문의 5요소 익히기</td>\n<td>문항 5개 + 해설</td>\n<td>Chat, 프롬프트</td>\n</tr>\n<tr>\n<td>2. 나만의 GPT 만들기</td>\n<td>15분</td>\n<td>반복 업무를 ‘지침’으로 고정</td>\n<td>맞춤형 GPT(또는 프로젝트) 1개</td>\n<td>워크플로우, 스킬 개념</td>\n</tr>\n<tr>\n<td>3. 미니 웹 도구(MVP)</td>\n<td>13분</td>\n<td>학생이 푸는 퀴즈 페이지</td>\n<td>HTML 파일 1개</td>\n<td>Code, MVP, 프론트엔드</td>\n</tr>\n</tbody></table>\n<span id=\"step-1\"></span><h3 id=\"1단계-프롬프트-다듬기-chat\">1단계: 프롬프트 다듬기 (Chat)</h3>\n<p>먼저 “평가 문제 만들어줘”만 입력해 결과를 본 뒤, 5요소(역할·대상·과제·조건·형식)를 넣어 비교한다.</p>\n<pre><code>너는 고등학교 [과목] 교사야. (역할)\n고[학년] 학생, 학습 수준은 중간이야. (대상)\n[단원명] 단원의 형성평가 문항 5개를 만들어 줘. (과제)\n객관식 3개, 서술형 2개. 각 문항에 성취기준을 표시해. (조건)\n표로: 번호 | 문항 | 정답 | 해설 | 성취기준 (형식)\n</code></pre>\n<p>확인 포인트: 정답·성취기준이 실제와 맞는지 교사가 검토한다(환각 체험).</p>\n<span id=\"step-2\"></span><h3 id=\"2단계-나만의-gpt-만들기-워크플로우\">2단계: 나만의 GPT 만들기 (워크플로우)</h3>\n<ol>\n<li>ChatGPT → GPT 탐색 → 만들기(유료) 또는 프로젝트 생성(무료 가능 범위 확인).</li>\n<li>‘지침’에 1단계 프롬프트를 고정 규칙으로 바꿔 넣는다(예: “항상 표 형식, 항상 성취기준 포함”).</li>\n<li>교육과정 성취기준 문서를 지식 파일로 올린다.</li>\n<li>단원명만 바꿔 2번 테스트 → 같은 품질이 나오는지 확인.</li>\n</ol>\n<p>개념 연결: ‘매번 설명하지 않아도 되는 지침’이 곧 스킬의 출발점이다.</p>\n<span id=\"step-3\"></span><h3 id=\"3단계-미니-웹-도구로-mvp\">3단계: 미니 웹 도구로 (MVP)</h3>\n<pre><code>위 문항 5개로 학생용 퀴즈 웹페이지를 만들어 줘.\n- HTML 파일 하나로, 인터넷만 있으면 열리게\n- 한 문제씩 보여주고, 제출하면 정답·해설 표시\n- 끝에 점수 표시, 학생 이름은 받지 말 것\n- 폰 화면에서도 보기 좋게\n</code></pre>\n<ul>\n<li>ChatGPT의 캨버스·미리보기 또는 Sites(베타)로 확인한다. 다운로드한 HTML을 더블클릭해도 열린다.</li>\n<li>“오답이면 힌트를 먼저 보여줘”처럼 한 가지씩 수정 요청 → 반복 개선을 체험한다.</li>\n<li>백엔드가 없으므로 점수는 저장되지 않는다 → ‘저장하려면 무엇이 필요할까?’로 1교시 용어와 연결.</li>\n</ul>\n<p><strong>공유(10분)</strong>: 2–3명이 화면을 보여 주고, “다음 주 내 수업에 쓸 한 가지”를 적어 낸다.</p>\n<span id=\"extras\"></span><h2 id=\"그-외-제안\">그 외 제안</h2>\n<p>입문자 3시간 연수의 성패는 <strong>강의를 줄이고 ‘내 일에 바로 쓴 경험’을 남기는 것</strong>에 달려 있다.</p>\n<ul>\n<li><strong>사전 설문(3문항)</strong>: 사용 경험, 유료 계정 여부, ‘가장 줄이고 싶은 업무’ → 3교시 주제를 맞춤화</li>\n<li><strong>계정 사전 준비</strong>: 당일 가입·인증에 10분 이상 사라진다. 연수 전날까지 로그인 확인</li>\n<li><strong>무료·유료 차이 대비</strong>: 맞춤형 GPT 만들기·Work는 요금제에 따라 다르다 → 무료 계정용 대체 경로(프로젝트·긴 지침 복사 사용) 준비</li>\n<li><strong>짝 실습</strong>: 입문자끼리 막히면 멈춘다. 숙련자 1명 + 입문자 1–2명으로 자리 배치</li>\n<li><strong>프롬프트 카드 배포</strong>: 5요소 템플릿 + 업무별 예시 10개를 A4 한 장으로</li>\n<li><strong>윤리·보안 5분 고정</strong>: 개인정보 미입력, 결과 검증, AI 사용 표시, 학교 계정 연동 전 확인</li>\n<li><strong>사후 과제</strong>: 2주 뒤 ‘실제로 써본 사례 1개’ 공유 → 학교 내 활용 사례집으로 축적</li>\n<li><strong>후속 연수 제안</strong>: 2차 연수에서 Work(에이전트)·스킬·MCP를 실제로 연결해 보기, 3차에서 PWA 배포까지</li>\n</ul>\n<span id=\"copilot\"></span><h2 id=\"부록-microsoft-copilot-활용법-부산-penz-계정-기준\">부록: Microsoft Copilot 활용법 (부산 PENZ 계정 기준)</h2>\n<p>부산 교사·학생은 2026년 9월부터 <strong>PENZ(펜즈) 계정 하나로 Microsoft 365에 로그인</strong>한다(교육디지털원패스 연계, 초1부터 고3까지 같은 계정). 이 부록은 PENZ가 Microsoft 365 교육용(A 라이선스) 계정이라는 전제로 쓴다. 학교 계정이라 추가 비용이 없고, 입력한 내용이 AI 학습에 쓰이지 않으며, 교육청이 학생 접근을 관리한다. 그래서 <strong>학생 수업은 PENZ Copilot이 기본 선택</strong>이다. 학생이 Copilot Chat을 쓰려면 교육청이 학생 계정에서 켜 둬야 한다. 유료 Microsoft 365 Copilot 라이선스 포함 여부는 공개 자료로 확인되지 않아, 아래 표의 ‘유료’ 항목은 연수 전 확인이 필요하다(<a href=\"https://nocutnews.co.kr/news/6554055\" target=\"_blank\" rel=\"noopener noreferrer\">노컷뉴스</a>, <a href=\"https://view.asiae.co.kr/article/2026072809321747042\" target=\"_blank\" rel=\"noopener noreferrer\">아시아경제</a>).</p>\n<p><strong>에듀 계정(Microsoft 365 A1·A3·A5)으로 무료인 것 vs 유료인 것</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">기능</th>\n<th scope=\"col\">무엇을 하나</th>\n<th scope=\"col\">교사</th>\n<th scope=\"col\">학생(13세+)</th>\n<th scope=\"col\">비용</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Microsoft 365 Copilot Chat</td>\n<td>대화형 AI. 웹 검색, 파일 업로드, 이미지 생성, Copilot Pages, 에이전트</td>\n<td>○</td>\n<td>○(관리자 활성화)</td>\n<td>무료</td>\n</tr>\n<tr>\n<td>Teach (Copilot 앱 안 교사 전용)</td>\n<td>수업 계획, 자료 수준 조절, 퀴즈·루브릭, 단원 계획(Unit Plans), 학습 활동(플래시카드 등)</td>\n<td>○</td>\n<td>—</td>\n<td>무료</td>\n</tr>\n<tr>\n<td>Copilot Notebooks + 학습 가이드</td>\n<td>내 자료를 모아 그 안에서만 답하는 작업 공간, 자료로 학습 가이드·자기 테스트 생성</td>\n<td>○</td>\n<td>○</td>\n<td>무료</td>\n</tr>\n<tr>\n<td>Study and Learn 에이전트</td>\n<td>학습 과학 기반 학습 동반자(개념 설명·연습·피드백)</td>\n<td>—</td>\n<td>○</td>\n<td>무료</td>\n</tr>\n<tr>\n<td>Learning Zone</td>\n<td>수업용 인터랙티브 레슨 생성·과제 연결</td>\n<td>○</td>\n<td>레슨 참여</td>\n<td>무료(생성은 Copilot+ PC, 일반 Windows 11은 2027-08-01까지 1회 10슬라이드)</td>\n</tr>\n<tr>\n<td>Microsoft 365 Copilot</td>\n<td>워드·엑셀·파워포인트 안 Copilot, Researcher·Analyst 에이전트</td>\n<td>△</td>\n<td>△</td>\n<td>유료 추가 라이선스(학교 구매)</td>\n</tr>\n</tbody></table>\n<p>연수 때 무료 범위와 유료 범위를 분명히 나눠 보여준다. “워드 안의 Copilot 버튼이 왜 안 되죠?”는 대부분 유료 라이선스 문제다.</p>\n<span id=\"copilot-chat\"></span><h3 id=\"①-copilot-chat-학교-계정으로-쓰는-chatgpt형-대화\">① Copilot Chat — 학교 계정으로 쓰는 ChatGPT형 대화</h3>\n<p>웹 검색, 파일 업로드, 이미지 생성, Copilot Pages(대화 결과를 함께 고치는 문서), 에이전트를 쓴다. ChatGPT 무료 버전과 비슷하지만 학교 데이터 보호가 적용된다.</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">하고 싶은 일</th>\n<th scope=\"col\">이렇게 요청</th>\n<th scope=\"col\">나오는 것</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>공문 요약</td>\n<td>PDF 공문을 올리고 “담임이 할 일·기한만 표로”</td>\n<td>할 일·기한·제출처 표</td>\n</tr>\n<tr>\n<td>수업 삽화</td>\n<td>“열대우림 단면도를 교과서 삽화 느낌으로, 글자 없이”</td>\n<td>생성 이미지(수업 자료에 바로 삽입)</td>\n</tr>\n<tr>\n<td>최신 자료 조사</td>\n<td>“2026년 고교학점제 관련 교육부 발표 요약, 출처 링크 포함”</td>\n<td>요약 + 출처 링크(원문 확인 필수)</td>\n</tr>\n<tr>\n<td>동료와 초안 협업</td>\n<td>답변을 Copilot Pages로 보내 공유</td>\n<td>동료가 함께 고치는 문서</td>\n</tr>\n</tbody></table>\n<p><strong>수업 연결 — Teams 과제에 AI 활동 넣기</strong>: Teams 교육용 과제에서 ‘Study and Learn 할당’ 또는 ‘Copilot 시작 프롬프트’를 넣을 수 있다(2026년 11월 전체 제공 예정 — 연수 당일 화면 확인). 예: 시작 프롬프트 “너는 내 설득문의 논리만 점검하는 코치야. 나대신 고쳐 쓰지 마.”를 과제에 붙이면 학생이 같은 규칙으로 시작한다(<a href=\"https://techcommunity.microsoft.com/blog/educationblog/whats-new-in-microsoft-edu-%E2%80%93-october-2026/4516290\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft EDU 2026년 10월</a>).</p>\n<span id=\"copilot-teach\"></span><h3 id=\"②-teach-교사-전용-수업-자료-공장\">② Teach — 교사 전용 수업 자료 공장</h3>\n<p>Copilot 앱 안의 교사 전용 화면이다. 빈 채팅창 대신 <strong>과목·학년·언어·성취기준·시간을 고르는 양식</strong>이 나와서, 프롬프트를 잘 몰라도 구성 요소가 빠지지 않는다. 결과는 워드·Forms로 저장하고 Teams 학급에 공유한다(<a href=\"https://support.microsoft.com/en-US/education/teach-in-the-microsoft-365-copilot-app\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft 지원</a>).</p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">메뉴</th>\n<th scope=\"col\">무엇을 만드나</th>\n<th scope=\"col\">결과 형태</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>수업 계획(Lesson Plan)</td>\n<td>차시 수업 계획. 35개국 교육과정 기준 중 선택 또는 내 자료 첨부</td>\n<td>워드 문서</td>\n</tr>\n<tr>\n<td>단원 계획(Unit Plans)</td>\n<td>여러 차시를 묶은 단원 흐름(2026년 10월 말 전체 제공 목표, 연수 전 메뉴 확인)</td>\n<td>워드 문서</td>\n</tr>\n<tr>\n<td>루브릭</td>\n<td>평가 기준·수준별 서술(워드 문서로 저장)</td>\n<td>표</td>\n</tr>\n<tr>\n<td>퀴즈</td>\n<td>내 자료 기반 문항</td>\n<td>Microsoft Forms 퀴즈(바로 배포)</td>\n</tr>\n<tr>\n<td>학습 활동</td>\n<td>플래시카드(힌트 포함). 빈칸 채우기 등은 순차 추가</td>\n<td>학생용 활동 링크</td>\n</tr>\n<tr>\n<td>콘텐츠 수정(Modify Content)</td>\n<td>기준 정렬 / 지시문 차별화 / 읽기 수준 조절 / 실생활 예시 추가</td>\n<td>수정된 텍스트·문서</td>\n</tr>\n</tbody></table>\n<p><strong>실제 예시 1 — 수업 계획 만들기</strong></p>\n<ol>\n<li>Teach → 수업 계획 선택.</li>\n<li>입력: 과목 ‘통합과학’, 학년 ‘고등학교 1학년’, 언어 ‘한국어’, 시간 ‘50분’, 내용 “기후변화와 에너지 전환, 모둠 토의 중심”.</li>\n<li>성취기준: 목록에 한국 교육과정이 없으면 <strong>성취기준 문장을 직접 붙여 넣거나 문서를 첨부</strong>한다.</li>\n<li>결과: 학습 목표 → 도입 → 전개(활동) → 정리 → 평가 구성의 초안. 워드로 저장.</li>\n<li>이어서 ‘이 수업으로 퀴즈 만들기’ → Forms 퀴즈 5문항 → Teams 과제로 배포.</li>\n</ol>\n<p><strong>실제 예시 2 — 읽기 수준 조절 (전후 비교, 연수용 예시로 직접 작성)</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">원문</th>\n<th scope=\"col\">기초 학력용 (핵심 용어 유지: 온실가스, 탄소중립)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>화석연료 연소 과정에서 배출되는 온실가스가 대기 중 누적됨에 따라 지표의 복사 평형이 교란되었으며, 이에 대응하기 위한 탄소중립 전략이 요구된다.</td>\n<td>석탄·석유를 태우면 <strong>온실가스</strong>가 나온다. 온실가스가 공기에 쌓이면 지구가 더워진다. 그래서 내보내는 양과 줄이는 양을 같게 만드는 <strong>탄소중립</strong>이 필요하다.</td>\n</tr>\n</tbody></table>\n<p>사용법: Teach → 콘텐츠 수정 → 텍스트 붙여넣기(또는 워드·PDF 업로드) → ‘읽기 수준 수정’ → 학년·수준 선택 → <strong>핵심 용어</strong> 칸에 ‘온실가스, 탄소중립’을 넣어 쉬운 말로 바뀌지 않게 한다.</p>\n<p><strong>나머지 수정 기능 활용 예</strong></p>\n<ul>\n<li>지시문 차별화: “보고서를 작성하시오” → 단계별 체크리스트 버전(도움이 필요한 학생용)과 심화 과제 버전을 동시에.</li>\n<li>실생활 예시 추가: ‘열의 전도’ 설명에 “뜨거운 국에 넣은 쇠숬가락이 뜨거워진다” 같은 예를 개수 지정해 추가.</li>\n<li>기준 정렬: 기존 활동지를 올리고 어느 성취기준에 해당하는지 표시·보강.</li>\n</ul>\n<p>한계: Teach 화면은 100개 이상 언어로 표시되지만, 한국 교육과정 기준 목록 제공 여부와 한국어 결과 품질은 연수 전 직접 확인해야 한다. 결과물은 초안이므로 사실·성취기준 일치를 교사가 검토한다.</p>\n<span id=\"copilot-notebooks\"></span><h3 id=\"③-copilot-notebooks-내-자료로만-답하는-지식방\">③ Copilot Notebooks — 내 자료로만 답하는 지식방</h3>\n<p>자료(참고 항목)를 모아 두면 Copilot이 <strong>그 자료를 근거로</strong> 답하는 작업 공간이다. Google NotebookLM과 비슷한 개념이며, Copilot 앱의 앱 목록(와플 메뉴)에 있다. 교육용 A1·A3·A5 사용자는 추가 비용 없이 개요 페이지, 마인드맵, 학습 가이드를 쓴다(학생은 13세 이상) (<a href=\"https://support.microsoft.com/en-US/education/copilot/copilot-notebook-study-guide\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft 지원</a>).</p>\n<p><strong>만들기 4단계</strong></p>\n<ol>\n<li>Copilot 앱 → Notebooks → 새 노트북, 이름 짓기(예: “통합사회 2단원 시험 대비”).</li>\n<li>참고 항목 추가: 워드·파워포인트·PDF·엑셀·OneNote 페이지·Copilot Pages·Teams 회의 메모.</li>\n<li>개요 페이지에서 전체 요약·핵심 주제를 확인하고, 채팅으로 질문한다.</li>\n<li>참고 항목 창의 + → <strong>학습 가이드</strong> → 넣을 페이지 선택 → 생성.</li>\n</ol>\n<p><strong>학습 가이드에 들어가는 것</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">페이지</th>\n<th scope=\"col\">내용</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>요약</td>\n<td>자료 전체 개요(항상 생성)</td>\n</tr>\n<tr>\n<td>주제 페이지</td>\n<td>핵심 주제마다 심화 설명과 생각 질문</td>\n</tr>\n<tr>\n<td>플래시카드</td>\n<td>앞면 질문·용어, 뒷면 답</td>\n</tr>\n<tr>\n<td>퀴즈</td>\n<td>Forms 기반 자기 테스트. <strong>결과는 비공개</strong>(교사 성적부로 안 감)</td>\n</tr>\n<tr>\n<td>빈칸 채우기·짝 맞추기</td>\n<td>용어·개념 연습</td>\n</tr>\n</tbody></table>\n<p>제약: 참고 자료 합계가 약 10만 자를 넘거나 보안 라벨이 붙은 파일이 있으면 요약·주제 페이지만 만들어지고 플래시카드·빈칸·짝 맞추기 등 활동은 빠질 수 있다. 단원 단위로 나눠 만든다.</p>\n<p><strong>실제 예시 — 학생</strong>: ‘통합사회 2단원 시험 대비’ 노트북에 수업 슬라이드·학습지 PDF·내 필기(OneNote)를 넣는다 → 학습 가이드의 플래시카드로 매일 10분 복습 → 시험 전날 퀴즈로 점검 → 틀린 주제는 “이 개념을 예시로 다시 설명해 줘”라고 채팅.</p>\n<p><strong>실제 예시 — 교사</strong>: ‘우리 학교 교육과정 지식방’ 노트북에 학교 교육과정 편성표·학업성적관리규정·평가 계획을 넣는다(학생 개인정보 없는 문서만) → “3학년 선택과목 개설 조건은?”, “수행평가 반영 비율 규정 조항”처럼 질문 → 근거 문서에 연결된 답. 마인드맵으로 신규 교사 안내 자료도 만든다.</p>\n<p><strong>수업 운영 팁</strong>: 교사가 단원 자료를 넣은 노트북을 만들어 학급과 공유해도, 플래시카드·퀴즈는 학생이 각자 생성해야 한다. 모둠별로 서로의 플래시카드로 문제를 내는 활동으로 연결하면 좋다.</p>\n<span id=\"copilot-learning-zone\"></span><h3 id=\"④-learning-zone-학생이-눌러-보며-배우는-인터랙티브-레슨\">④ Learning Zone — 학생이 눌러 보며 배우는 인터랙티브 레슨</h3>\n<p>설명을 입력하면 <strong>내용 슬라이드와 연습 문제가 섞인 레슨</strong>을 만들고, 학생에게 내준 뒤 누가 어디서 막혔는지 리포트로 본다. Windows 앱이며 교육용 A1·A3·A5에 포함된다(<a href=\"https://support.microsoft.com/en-us/education/getting-started-with-microsoft-learning-zone\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft 지원</a>, <a href=\"https://learningzone.microsoft.com/\" target=\"_blank\" rel=\"noopener noreferrer\">learningzone.microsoft.com</a>).</p>\n<p><strong>레슨 만들고 내주기 흐름</strong></p>\n<ol>\n<li>새 레슨 → 레슨 설명 입력, 성취기준·학년·활동 유형·언어·슬라이드 수 설정, ‘레슨 균형’ 슬라이더로 설명:연습 비율 조절.</li>\n<li>AI가 레슨 개요를 먼저 만든다 → 교사가 항목을 고치거나 순서를 바꾼다.</li>\n<li>레슨 생성 → 슬라이드가 하나씩 만들어진다. 검토하지 않은 AI 슬라이드에는 <strong>보라색 점</strong>이 붙어, 모두 확인하기 전에는 공유 전 알림이 뜬다.</li>\n<li>슬라이드 다시 생성·문장 쉽게 하기·이미지 추가 → ‘학생 보기’로 직접 풀어 본다.</li>\n<li>공유: 짧은 코드, 링크, Teams 과제, LMS. 교사가 화면을 이끄는 실시간 수업 모드도 있다.</li>\n<li>리포트 탭: 과제별 참여 인원·평균, 학생·문항별로 어려워한 곳을 확인.</li>\n</ol>\n<p><strong>쓰기 전에 꼭 알아야 할 제약</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">항목</th>\n<th scope=\"col\">현재 상태(발표 기준)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>레슨 생성 기기</td>\n<td>Copilot+ PC. 일반 Windows 11 PC도 2027-08-01까지 생성 가능(1회 최대 10슬라이드)</td>\n</tr>\n<tr>\n<td>레슨 생성 언어</td>\n<td><strong>영어·스페인어</strong>·프랑스어·이탈리아어·일본어·포르투갈어(브라질). 한국어는 현재 목록에 없음</td>\n</tr>\n<tr>\n<td>앱 화면 언어</td>\n<td>50개 이상(한국어 화면 사용 가능성)</td>\n</tr>\n<tr>\n<td>AI 없이 쓸 수 있는 것</td>\n<td>파트너 레슨 라이브러리, 과제 배포, 리포트</td>\n</tr>\n</tbody></table>\n<p><strong>실제 예시 — 영어 수업(생성 언어 제약에 맞춘 추천)</strong>: “High school grade 10, reading lesson on climate change vocabulary, 10 slides, include matching and short-answer practice” → 개요 확인 → 생성 → 보라점 슬라이드 검토 → 짧은 코드로 학생에게 공유 → 리포트에서 오답이 많은 어휘를 다음 수업 도입에 반영.</p>\n<p><strong>다른 교과는</strong>: 한국어 생성이 지원되지 않으므로 ① 파트너 레슨 라이브러리에서 고르거나 ② 빈 레슨에 직접 슬라이드·문항을 넣고 배포·리포트 기능만 쓴다.</p>\n<p><strong>접속 방법</strong></p>\n<ol>\n<li>PENZ에 교육디지털원패스로 로그인한 뒤 Microsoft 365를 연다. 또는 m365.cloud.microsoft(Microsoft 365 Copilot 앱)에 <strong>PENZ 계정</strong>으로 로그인한다. 개인 Microsoft 계정이 아니다.</li>\n<li>Copilot 화면에 방패(데이터 보호) 표시가 있는지 확인한다. 있으면 입력 내용이 학습에 쓰이지 않는 학교 계정 상태다.</li>\n<li>교사는 앱 왼쪽에서 Teach, 학생은 Notebooks·에이전트를 찾는다(메뉴 이름·위치는 업데이트로 바뀔 수 있음).</li>\n<li>내 라이선스 확인: myaccount.microsoft.com → 구독. “Microsoft 365 Copilot”이 보이면 워드·엑셀·파워포인트 안 Copilot까지, A1·A3 등만 보이면 Copilot Chat까지다.</li>\n</ol>\n<p><strong>교사 활용 — 바로 해 볼 4가지</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">하고 싶은 일</th>\n<th scope=\"col\">도구</th>\n<th scope=\"col\">이렇게 요청</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>단원 수업 계획</td>\n<td>Teach → 수업 계획 / 단원 계획</td>\n<td>“고1 통합과학 기후변화 단원 4차시, 활동 중심, 성취기준 포함”</td>\n</tr>\n<tr>\n<td>자료 수준 맞추기</td>\n<td>Teach → 콘텐츠 수정</td>\n<td>읽기 자료를 올리고 “기초 학력 학생용으로 쉽게, 어휘 풀이 포함”</td>\n</tr>\n<tr>\n<td>형성평가·루브릭</td>\n<td>Teach → 퀴즈 / 루브릭</td>\n<td>“문항 5개, 오답 해설 포함” → Forms·Teams 과제로 연결</td>\n</tr>\n<tr>\n<td>단원 자료 지식방</td>\n<td>Copilot Notebooks</td>\n<td>교육과정·교재·워크시트를 모아 “이 자료 안에서만 답해”</td>\n</tr>\n</tbody></table>\n<p><strong>학생 활용 — 수업 안에서</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\">장면</th>\n<th scope=\"col\">도구</th>\n<th scope=\"col\">학생이 하는 일</th>\n<th scope=\"col\">교사가 확인할 것</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>시험 대비 복습</td>\n<td>Notebooks 학습 가이드</td>\n<td>수업 자료를 넣고 자기 테스트</td>\n<td>퀴즈 결과는 학생이 공유해야 보인다</td>\n</tr>\n<tr>\n<td>개념이 막힐 때</td>\n<td>Study and Learn 에이전트</td>\n<td>답 대신 힌트·질문으로 이해</td>\n<td>대화 기록을 성찰지로 제출</td>\n</tr>\n<tr>\n<td>글쓰기 피드백</td>\n<td>Copilot Chat</td>\n<td>초안을 올리고 “논리 빈틈만 지적, 고쳐 쓰지 마”</td>\n<td>AI 사용 표시 규칙</td>\n</tr>\n<tr>\n<td>조사 활동</td>\n<td>Copilot Chat(웹 검색)</td>\n<td>답변의 출처 링크를 열어 직접 확인</td>\n<td>출처와 내용 일치 여부</td>\n</tr>\n</tbody></table>\n<p><strong>ChatGPT와 어떻게 나눠 쓸까</strong></p>\n<table>\n<thead>\n<tr>\n<th scope=\"col\"><span class=\"sr-only\">구분</span></th>\n<th scope=\"col\">Microsoft Copilot(에듀)</th>\n<th scope=\"col\">ChatGPT</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>비용</td>\n<td>PENZ 계정으로 무료(Chat·Teach·Notebooks)</td>\n<td>무료 + 유료 기능(Work·Sites·스킬)</td>\n</tr>\n<tr>\n<td>학생 사용</td>\n<td>학교가 관리하는 계정, 관리자 통제</td>\n<td>PENZ로도 제공됨 — 플랜·학생 허용 범위는 확인 필요</td>\n</tr>\n<tr>\n<td>강점</td>\n<td>Teams·OneNote·Forms·과제와 연결, 교사 전용 Teach</td>\n<td>에이전트(Work), 웹앱(Sites), 스킬·플러그인 생태계</td>\n</tr>\n<tr>\n<td>추천 용도</td>\n<td><strong>학생 수업</strong>, 수업 준비</td>\n<td><strong>교사 업무 자동화</strong>, 도구 만들기</td>\n</tr>\n</tbody></table>\n<p><strong>관리자(학교·교육청 정보 담당)에게 미리 확인</strong></p>\n<ul>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> PENZ Microsoft 365 라이선스가 A1·A3·A5 중 무엇이고, 유료 Microsoft 365 Copilot이 포함되는지(교사·학생 각각)</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 학생 계정 연령대 설정과 Copilot Chat 활성화 여부(고등학생은 13세 이상 기준)</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> Notebooks·Study and Learn 에이전트·Teach 허용 여부</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 연수 전 테스트용 학생 PENZ 계정 1개로 실제 접속 확인</li>\n<li><span aria-hidden=\"true\">☐</span><span class=\"sr-only\">점검 항목:</span> 문의처: 부산교육청 교육연구정보원(PENZ 담당)</li>\n</ul>\n<p><strong>연수 운영 팁(부록 20분 버전)</strong>: Teach로 같은 단원 퀴즈를 만들어 3교시 ChatGPT 결과와 비교(10분) → 학생 계정으로 Notebooks 학습 가이드 시연(10분).</p>\n<p>참고: Teach의 한국어 지원 범위, 기능 이름·메뉴 위치는 국가·업데이트에 따라 다를 수 있다. 연수 전 실제 화면으로 확인한다. <strong>2026-11-26 확인: 교육청(PENZ) 교사 계정의 Copilot 화면에는 Teach 메뉴가 없고 ‘학습’ 메뉴만 있었다. 연수 때 Teach 시연이 가능한지 먼저 확인한다.</strong></p>\n<p>출처: <a href=\"https://www.microsoft.com/en-gb/education/products/copilot-in-education\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft — Copilot in education</a> · <a href=\"https://techcommunity.microsoft.com/blog/educationblog/microsoft-365-copilot-chat-for-students-13/4440370\" target=\"_blank\" rel=\"noopener noreferrer\">Copilot Chat for Students 13+</a> · <a href=\"https://techcommunity.microsoft.com/blog/educationblog/copilot-notebooks-and-study-guide-now-available-to-copilot-chat-users/4527320\" target=\"_blank\" rel=\"noopener noreferrer\">Copilot Notebooks·Study guide</a> · <a href=\"https://techcommunity.microsoft.com/blog/educationblog/whats-new-in-microsoft-edu-%E2%80%93-october-2026/4516290\" target=\"_blank\" rel=\"noopener noreferrer\">What&#39;s New in Microsoft EDU — 2026년 10월</a> · <a href=\"https://news.microsoft.com/2026/06/24/microsofts-new-ai-in-education-report-highlights-widespread-adoption-and-increasing-demand-for-support/\" target=\"_blank\" rel=\"noopener noreferrer\">Microsoft AI in Education 발표(2026-06)</a></p>\n<span id=\"sources\"></span><h2 id=\"출처\">출처</h2>\n<ul>\n<li><a href=\"https://openai.com/index/chatgpt-for-your-most-ambitious-work\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI — ChatGPT Work 발표(2026-07-09)</a></li>\n<li><a href=\"https://help.openai.com/en/articles/11487775-apps-in-chatgpt?gn=1\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI 도움말 — Apps in ChatGPT(커넥터 → 앱 명칭 변경)</a></li>\n<li><a href=\"https://help.openai.com/articles/12584461\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI 도움말 — 커스텀 MCP 서버 연결</a></li>\n<li><a href=\"https://claude.com/docs/cowork\" target=\"_blank\" rel=\"noopener noreferrer\">Claude 문서 — Cowork</a></li>\n</ul>\n<ul>\n<li><a href=\"https://help.openai.com/en/articles/20001339\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI 도움말 — ChatGPT Sites 만들기·관리</a></li>\n<li><a href=\"https://openai.com/academy/chatgpt-sites\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI Academy — ChatGPT Sites</a></li>\n<li><a href=\"https://openai.com/academy/skills\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI Academy — 스킬 사용하기</a></li>\n<li><a href=\"https://help.openai.com/en/articles/20001256-plugins-in-chatgpt-and-codex\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI 도움말 — ChatGPT·Codex 플러그인</a></li>\n<li><a href=\"https://openai.com/index/learn-teach-chatgpt-work-codex\" target=\"_blank\" rel=\"noopener noreferrer\">OpenAI — 교육용 플러그인 발표(2026-08-04)</a></li>\n</ul>\n";
export const GUIDE_TOC: { id: string; text: string; level: 2 | 3 }[] = [{"id":"연수-개요","text":"연수 개요","level":2},{"id":"1교시-가-llm의-개념-챗봇-워크플로우-ai-에이전트","text":"1교시 (가) LLM의 개념: 챗봇 → 워크플로우 → AI 에이전트","level":2},{"id":"1교시-나-필수-용어-정리","text":"1교시 (나) 필수 용어 정리","level":2},{"id":"1교시-나-용어-실전-퀴즈-앱-하나-뜯어보기","text":"1교시 (나+) 용어 실전: 퀴즈 앱 하나 뜯어보기","level":2},{"id":"2교시-다-상용-ai-지도와-chat-work-code","text":"2교시 (다) 상용 AI 지도와 Chat / Work / Code","level":2},{"id":"2교시-다-1-chatgpt-work-자세히","text":"2교시 (다-1) ChatGPT Work 자세히","level":2},{"id":"2교시-다-2-chatgpt-sites-자세히","text":"2교시 (다-2) ChatGPT Sites 자세히","level":2},{"id":"2교시-라-스킬과-mcp","text":"2교시 (라) 스킬과 MCP","level":2},{"id":"2교시-라-1-스킬플러그인mcp-실제-적용하기","text":"2교시 (라-1) 스킬·플러그인·MCP 실제 적용하기","level":2},{"id":"①-플러그인-설치-mcp-연결-chatgpt","text":"① 플러그인 설치 = MCP 연결 (ChatGPT)","level":3},{"id":"②-스킬-만들기-chatgpt","text":"② 스킬 만들기 (ChatGPT)","level":3},{"id":"③-더-나아가기","text":"③ 더 나아가기","level":3},{"id":"2교시-라-2-추천-스킬mcp와-시연","text":"2교시 (라-2) 추천 스킬·MCP와 시연","level":2},{"id":"활동-학교-업무-알맞은-ai-짝짓기","text":"활동: 학교 업무 ↔ 알맞은 AI 짝짓기","level":2},{"id":"고등학생과-llm으로-수업한다면","text":"고등학생과 LLM으로 수업한다면","level":2},{"id":"3교시-실습-프로젝트-3단계-chatgpt","text":"3교시 실습 프로젝트 3단계 (ChatGPT)","level":2},{"id":"1단계-프롬프트-다듬기-chat","text":"1단계: 프롬프트 다듬기 (Chat)","level":3},{"id":"2단계-나만의-gpt-만들기-워크플로우","text":"2단계: 나만의 GPT 만들기 (워크플로우)","level":3},{"id":"3단계-미니-웹-도구로-mvp","text":"3단계: 미니 웹 도구로 (MVP)","level":3},{"id":"그-외-제안","text":"그 외 제안","level":2},{"id":"부록-microsoft-copilot-활용법-부산-penz-계정-기준","text":"부록: Microsoft Copilot 활용법 (부산 PENZ 계정 기준)","level":2},{"id":"①-copilot-chat-학교-계정으로-쓰는-chatgpt형-대화","text":"① Copilot Chat — 학교 계정으로 쓰는 ChatGPT형 대화","level":3},{"id":"②-teach-교사-전용-수업-자료-공장","text":"② Teach — 교사 전용 수업 자료 공장","level":3},{"id":"③-copilot-notebooks-내-자료로만-답하는-지식방","text":"③ Copilot Notebooks — 내 자료로만 답하는 지식방","level":3},{"id":"④-learning-zone-학생이-눌러-보며-배우는-인터랙티브-레슨","text":"④ Learning Zone — 학생이 눌러 보며 배우는 인터랙티브 레슨","level":3},{"id":"출처","text":"출처","level":2}];
export const GUIDE_ALIASES: Record<string, string> = {"overview":"연수-개요","period-1":"1교시-가-llm의-개념-챗봇-워크플로우-ai-에이전트","terms":"1교시-나-필수-용어-정리","quiz-app":"1교시-나-용어-실전-퀴즈-앱-하나-뜯어보기","period-2":"2교시-다-상용-ai-지도와-chat-work-code","chatgpt-work":"2교시-다-1-chatgpt-work-자세히","chatgpt-sites":"2교시-다-2-chatgpt-sites-자세히","skills":"2교시-라-스킬과-mcp","skills-mcp-practice":"2교시-라-1-스킬플러그인mcp-실제-적용하기","mcp":"①-플러그인-설치-mcp-연결-chatgpt","skill-create":"②-스킬-만들기-chatgpt","recommended":"2교시-라-2-추천-스킬mcp와-시연","matching-activity":"활동-학교-업무-알맞은-ai-짝짓기","high-school":"고등학생과-llm으로-수업한다면","period-3":"3교시-실습-프로젝트-3단계-chatgpt","practice-steps":"3교시-실습-프로젝트-3단계-chatgpt","step-1":"1단계-프롬프트-다듬기-chat","step-2":"2단계-나만의-gpt-만들기-워크플로우","step-3":"3단계-미니-웹-도구로-mvp","extras":"그-외-제안","copilot":"부록-microsoft-copilot-활용법-부산-penz-계정-기준","copilot-chat":"①-copilot-chat-학교-계정으로-쓰는-chatgpt형-대화","copilot-teach":"②-teach-교사-전용-수업-자료-공장","copilot-notebooks":"③-copilot-notebooks-내-자료로만-답하는-지식방","copilot-learning-zone":"④-learning-zone-학생이-눌러-보며-배우는-인터랙티브-레슨","sources":"출처"};
